<script>
  import { onMount, tick } from 'svelte';
  import WindowControls from './WindowControls.svelte';
  import { newsWindow, newsStory, newsVisibleStories, newsCapabilities } from './news-state.js';
  import { newsMenus } from './news-menus.js';
  import { createNewsNativeView } from './news-native-view.js';
  import './news.css';
  let { state: newsState, profile, windowId, execute, registerView, available=true, active=true, controls={} } = $props();
  let root=$state(null),message=$state('');
  let originalState,originalProfile,originalWindowId,retired=false,facade;
  const session=$derived(newsWindow(newsState,windowId));
  const story=$derived(newsStory(newsState,session?.storyId));
  const cap=$derived(newsCapabilities(profile,newsState.preferences.region));
  const feed=$derived(newsVisibleStories(newsState,session??{section:'today',query:''}));
  const menus=$derived(newsMenus(profile,newsState,windowId));
  const menu=$derived(menus.find(row=>row.id===session?.menu));
  const channels=$derived(newsState.channels.filter(row=>row.regions.includes(newsState.preferences.region)&&(!session?.query||row.name.toLocaleLowerCase('en-US').includes(session.query.toLocaleLowerCase('en-US')))));
  const topics=$derived(newsState.topics.filter(row=>!session?.query||row.name.toLocaleLowerCase('en-US').includes(session.query.toLocaleLowerCase('en-US'))));
  const sectionTitle=$derived(session?.section.startsWith('channel:')?newsState.channels.find(row=>row.id===session.section.slice(8))?.name:session?.section.startsWith('topic:')?newsState.topics.find(row=>row.id===session.section.slice(6))?.name:({today:'Top Stories',saved:'Saved Stories',history:'History',following:'Discover Channels & Topics',search:'Search'}[session?.section]??'Today'));
  const date=$derived(new Intl.DateTimeFormat(newsState.preferences.region==='US'?'en-US':newsState.preferences.region==='UK'?'en-GB':newsState.preferences.region==='AU'?'en-AU':'en-CA',{month:'long',day:'numeric',timeZone:'UTC'}).format(new Date(feed[0]?.publishedAt??0)));
  function current(){return !retired&&root?.isConnected&&newsState===originalState&&profile===originalProfile&&windowId===originalWindowId;}
  async function request(name,payload={}){if(!current()||!available||!active)return;const result=await execute(name,{windowId},payload);if(current())message=result?.status==='applied'?'':result?.error?.message??'The actual News operation is unavailable.';return result;}
  function navigate(section){return request('news.navigate',{section});}
  function follow(kind,id,following){return request('news.follow',{kind,id,following});}
  async function menuRequest(item){if(!item.enabled||!item.request)return;const result=await execute(item.request.command,item.request.target,item.request.payload);if(current())message=result?.status==='applied'?'':result?.error?.message??'Unavailable.';if(current()&&result?.status==='applied'&&session?.menu)request('news.menu.close',{restoreFocus:false});}
  function keyboard(event){if(!current()||!available||!active)return;if(event.key==='Escape'){event.preventDefault();if(session?.sheet)request('news.sheet.close');else if(session?.menu)request('news.menu.close',{restoreFocus:true});else if(story)request('news.story.close');}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='f'){event.preventDefault();request('news.native.focus',{controlId:'search'});}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='s'&&story){event.preventDefault();request('news.story.save',{storyId:story.id,saved:!newsState.saved.includes(story.id)});}}
  onMount(()=>{originalState=newsState;originalProfile=profile;originalWindowId=windowId;facade=createNewsNativeView({getRoot:()=>root,available:()=>current()&&available&&active,tick,windowId});registerView(windowId,facade);return()=>{retired=true;facade.destroy();registerView(originalWindowId,null,facade);};});
</script>

<section bind:this={root} class="news-app" class:classic={cap.classic} class:golden={cap.golden} class:windows={cap.windows} class:equivalent={!cap.native} class:inactive={!active} data-news-window-id={windowId} data-profile={profile.id} aria-label={cap.label} role="region" tabindex="-1" onkeydown={keyboard}>
  <div class="news-main" inert={!available||!active||!!session?.sheet}>
    <header class="news-toolbar">
      {#if !cap.windows}<WindowControls {active} onclose={()=>request('news.window.close')} onminimize={controls.onminimize} onzoom={controls.onzoom} onfullscreen={controls.onfullscreen} onsplitbegin={controls.onsplitbegin} onsplitside={controls.onsplitside} ongreenmenu={controls.ongreenmenu} fullScreen={controls.fullScreen} revealedTop={controls.revealedTop} modernGreenMenu={controls.modernGreenMenu} zoomed={controls.zoomed}/>{/if}
      <button data-news-control="sidebar" aria-label={session?.sidebar?'Hide Sidebar':'Show Sidebar'} title="Sidebar" onclick={()=>request('news.sidebar.set',{visible:!session?.sidebar})}>▤</button>
      <button data-news-control="back" aria-label="Back to feed" disabled={!story} onclick={()=>request('news.story.close')}>‹</button>
      <strong>{cap.label}</strong>
      {#if story}<button data-news-control="save" aria-label={newsState.saved.includes(story.id)?'Unsave Story':'Save Story'} class:pressed={newsState.saved.includes(story.id)} onclick={()=>request('news.story.save',{storyId:story.id,saved:!newsState.saved.includes(story.id)})}>▱</button><button data-news-control="share" title="Share Story" onclick={()=>request('news.story.share',{storyId:story.id})}>↥</button>{/if}
      <button data-news-control="preferences" title={cap.classic?'Preferences':'Settings'} onclick={()=>request('news.sheet.open',{sheet:'preferences'})}>⚙</button>
    </header>
    <nav class="news-menu-strip" aria-label="News menus">{#each menus as row}<button data-news-control={`menu:${row.id}`} aria-haspopup="menu" aria-expanded={session?.menu===row.id} onclick={()=>session?.menu===row.id?request('news.menu.close',{restoreFocus:false}):request('news.menu.open',{menuId:row.id})}>{row.label}</button>{/each}</nav>
    {#if menu}<div class="news-menu" role="menu" aria-label={menu.label}>{#each menu.items as item}{#if item.separator}<hr/>{:else}<button role="menuitem" disabled={!item.enabled} data-news-control={`menu-item:${item.id}`} onclick={()=>menuRequest(item)}><span>{item.checked?'✓ ':''}{item.label}</span><small>{item.shortcut??''}</small></button>{/if}{/each}</div>{/if}
    <div class="news-layout">
      {#if session?.sidebar}<aside class="news-sidebar" data-news-area="sidebar" aria-label="News sidebar">
        <label class="news-search">⌕ <input data-news-control="search" type="search" value={session.query} placeholder="Search" aria-label="Search stories, channels and topics" oninput={event=>request('news.search',{query:event.currentTarget.value})}/></label>
        <h3>APPLE NEWS</h3>
        {#each [['today','▧','Today'],['saved','▱','Saved Stories'],['history','◷','History']] as [id,icon,label]}<button data-news-control={`section:${id}`} class:selected={session.section===id&&!story} onclick={()=>navigate(id)}><span>{icon}</span>{label}{#if id==='saved'}<small>{newsState.saved.length}</small>{/if}</button>{/each}
        <h3>Following</h3>
        {#each newsState.channels.filter(row=>newsState.followingChannels.includes(row.id)&&row.regions.includes(newsState.preferences.region)) as channel}<button data-news-control={`channel:${channel.id}`} class:selected={session.section===`channel:${channel.id}`} onclick={()=>navigate(`channel:${channel.id}`)}><span class="news-channel-icon" style={`background:${channel.color}`}>{channel.name.slice(0,1)}</span>{channel.name}</button>{/each}
        {#each newsState.topics.filter(row=>newsState.followingTopics.includes(row.id)) as topic}<button data-news-control={`topic:${topic.id}`} class:selected={session.section===`topic:${topic.id}`} onclick={()=>navigate(`topic:${topic.id}`)}><span>♯</span>{topic.name}</button>{/each}
        <button class="news-discover" data-news-control="discover" onclick={()=>navigate('following')}>Discover Channels & Topics</button>
      </aside>{:else}<input class="news-hidden-sidebar-search" data-news-control="search" type="search" value={session?.query??''} placeholder="Search" aria-label="Search stories" oninput={event=>request('news.search',{query:event.currentTarget.value})}/>{/if}
      {#if story}<article class="news-reader" data-news-area="reader" class:small={newsState.preferences.textSize==='small'} class:large={newsState.preferences.textSize==='large'}>
        <div class="news-reader-brand">{newsState.channels.find(row=>row.id===story.channelId)?.name}</div>
        <h1>{story.title}</h1><p class="news-deck">{story.summary}</p><div class="news-byline">By {story.author} · {new Intl.DateTimeFormat('en-GB',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(story.publishedAt))}</div>
        <div class="news-reader-actions"><button data-news-control="reader:follow" onclick={()=>follow('channel',story.channelId,!newsState.followingChannels.includes(story.channelId))}>{newsState.followingChannels.includes(story.channelId)?'Following ✓':'Follow Channel +'}</button><button data-news-control="reader:save" onclick={()=>request('news.story.save',{storyId:story.id,saved:!newsState.saved.includes(story.id)})}>{newsState.saved.includes(story.id)?'Saved ✓':'Save Story'}</button><button data-news-control="reader:share" onclick={()=>request('news.story.share',{storyId:story.id})}>Share…</button><button data-news-control="reader:notify" disabled={!newsState.preferences.notificationsEnabled} onclick={()=>request('news.story.notify',{storyId:story.id})}>Send local alert</button></div>
        <div class="news-body">{#each story.paragraphs as paragraph}<p>{paragraph}</p>{/each}</div><p class="news-fiction-note">Original local fiction · complete offline story · no external reporting</p>
      </article>{:else}<main class="news-feed" data-news-area="feed" aria-label={sectionTitle}>
        {#if session?.section==='today'}<div class="news-masthead"><strong>News</strong><span>{date}</span><small>LOCAL EDITION · {newsState.preferences.region}</small></div>{/if}
        <div class="news-section-heading"><h1>{newsState.preferences.restrictToday&&session?.section==='today'?'Following':sectionTitle}</h1>{#if session?.section==='history'}<button data-news-control="clear-history" disabled={!newsState.history.length&&!newsState.recommendations.length} onclick={()=>request('news.sheet.open',{sheet:'clear-history'})}>Clear…</button>{/if}{#if session?.section.startsWith('channel:')}<button data-news-control="channel-follow" onclick={()=>follow('channel',session.section.slice(8),!newsState.followingChannels.includes(session.section.slice(8)))}>{newsState.followingChannels.includes(session.section.slice(8))?'Following ✓':'Follow +'}</button>{/if}{#if session?.section.startsWith('topic:')}<button data-news-control="topic-follow" onclick={()=>follow('topic',session.section.slice(6),!newsState.followingTopics.includes(session.section.slice(6)))}>{newsState.followingTopics.includes(session.section.slice(6))?'Following ✓':'Follow +'}</button>{/if}</div>
        {#if ['following','search'].includes(session?.section)}<div class="news-discovery"><h2>Channels</h2>{#each channels as channel}<div><button data-news-control={`discover-channel:${channel.id}`} onclick={()=>navigate(`channel:${channel.id}`)}><span class="news-channel-icon" style={`background:${channel.color}`}>{channel.name[0]}</span>{channel.name}</button><button data-news-control={`follow-channel:${channel.id}`} aria-label={`${newsState.followingChannels.includes(channel.id)?'Unfollow':'Follow'} ${channel.name}`} onclick={()=>follow('channel',channel.id,!newsState.followingChannels.includes(channel.id))}>{newsState.followingChannels.includes(channel.id)?'✓':'+'}</button></div>{/each}<h2>Topics</h2>{#each topics as topic}<div><button data-news-control={`discover-topic:${topic.id}`} onclick={()=>navigate(`topic:${topic.id}`)}>{topic.name}</button><button data-news-control={`follow-topic:${topic.id}`} aria-label={`${newsState.followingTopics.includes(topic.id)?'Unfollow':'Follow'} ${topic.name}`} onclick={()=>follow('topic',topic.id,!newsState.followingTopics.includes(topic.id))}>{newsState.followingTopics.includes(topic.id)?'✓':'+'}</button></div>{/each}</div>{/if}
        {#if session?.section!=='following'}<div class="news-cards" class:list={cap.classic&&['saved','history'].includes(session?.section)}>{#each feed as item,index}<article class="news-card" class:lead={index===0}>
          <button class="news-story-link" data-news-control={`story:${item.id}`} onclick={()=>request('news.story.open',{storyId:item.id})}>
            <div class="news-art" class:science={item.topicIds.includes('science')} class:culture={item.topicIds.includes('culture')} class:business={item.topicIds.includes('business')} aria-label="Authored editorial illustration" role="img"><svg viewBox="0 0 400 220" aria-hidden="true"><rect width="400" height="220" fill="currentColor"/>{#if item.topicIds.includes('science')}<path d="M0 155 Q80 95 170 151 T400 140 V220 H0Z" fill="#86abb0"/><path d="M0 180 Q100 125 200 175 T400 169" stroke="#e0ece8" stroke-width="7" fill="none"/><path d="M255 143V61m0 27l-45-30m45 57l45-42" stroke="#466246" stroke-width="8"/>{:else if item.topicIds.includes('culture')}<path d="M77 50L205 32 319 76 279 181 123 190Z" fill="#e7ba7b"/><path d="M123 190L205 32 207 161 319 76" fill="none" stroke="#ffecd1" stroke-width="4"/><circle cx="75" cy="150" r="31" fill="#ba655b"/>{:else if item.topicIds.includes('business')}<rect x="60" y="135" width="55" height="58" fill="#9ebac6"/><rect x="138" y="93" width="55" height="100" fill="#e3b264"/><rect x="216" y="50" width="55" height="143" fill="#e8e7d8"/><path d="M52 120L133 75 206 92 310 32" stroke="#44515c" stroke-width="5" fill="none"/>{:else}<circle cx="311" cy="53" r="27" fill="#ebc274"/><path d="M0 163L70 127 140 170 205 135 290 169 400 129V220H0Z" fill="#68847b"/><path d="M66 151V69L153 36 240 69V161Z" fill="#e7dfcb"/><rect x="94" y="79" width="36" height="45" fill="#7695a3"/><rect x="167" y="79" width="36" height="45" fill="#7695a3"/><rect x="133" y="129" width="41" height="51" fill="#9e735c"/>{/if}</svg><small>LOCAL FICTION</small></div>
            <div class="news-card-copy"><div class="news-publisher">{newsState.channels.find(row=>row.id===item.channelId)?.name}</div><h2>{item.title}</h2>{#if cap.classic||index===0}<p>{item.summary}</p>{/if}</div>
          </button><footer><span>{item.author}</span><button data-news-control={`save:${item.id}`} aria-label={`${newsState.saved.includes(item.id)?'Unsave':'Save'} ${item.title}`} class:pressed={newsState.saved.includes(item.id)} onclick={()=>request('news.story.save',{storyId:item.id,saved:!newsState.saved.includes(item.id)})}>{newsState.saved.includes(item.id)?'✓ Saved':'Save'}</button></footer>
        </article>{/each}</div>{#if !feed.length}<p class="news-empty">{session?.section==='saved'?'Saved stories appear here. Save a story from Today or a channel.':session?.section==='history'?'Stories you read appear here.':'No local stories match. Change your search, region or followed channels.'}</p>{/if}{/if}
      </main>{/if}
    </div><footer class="news-status" role="status">{message||cap.disclosure}</footer>
  </div>
  {#if session?.sheet}<div class="news-backdrop"><section class="news-dialog" role="dialog" aria-modal="true" aria-label={session.sheet==='preferences'?'News preferences':session.sheet==='clear-history'?'Clear History':'News Help'} data-news-area="dialog">
    <h1>{session.sheet==='preferences'?(cap.classic?'News Preferences':'News Settings'):session.sheet==='clear-history'?'Clear History':'About '+cap.label}</h1>
    {#if session.sheet==='preferences'}<label>Local edition <select data-news-control="region" value={newsState.preferences.region} onchange={event=>request('news.preferences.set',{values:{region:event.currentTarget.value}})}>{#each [['US','United States'],['UK','United Kingdom'],['AU','Australia'],['CA','Canada']] as [id,label]}<option value={id}>{label}{cap.classic&&id==='CA'?' — local equivalent only':''}</option>{/each}</select></label><label><input data-news-control="restrict-today" type="checkbox" checked={newsState.preferences.restrictToday} onchange={event=>request('news.preferences.set',{values:{restrictToday:event.currentTarget.checked}})}/> Restrict stories in Today</label><p>Show only followed channels in Today. No Top Stories or Trending Stories when restricted.</p><label><input data-news-control="restrict-explicit" type="checkbox" checked={newsState.preferences.restrictExplicit} onchange={event=>request('news.preferences.set',{values:{restrictExplicit:event.currentTarget.checked}})}/> Restrict stories with explicit content</label><label>Reader text <select data-news-control="text-size" value={newsState.preferences.textSize} onchange={event=>request('news.preferences.set',{values:{textSize:event.currentTarget.value}})}><option value="small">Small</option><option value="medium">Medium</option><option value="large">Large</option></select></label><label><input data-news-control="notifications-enabled" type="checkbox" checked={newsState.preferences.notificationsEnabled} onchange={event=>request('news.preferences.set',{values:{notificationsEnabled:event.currentTarget.checked}})}/> Allow authored local story alerts</label><p>Region, text size and alert toggle are local scene controls. Existing alerts are managed in the shared Notification Center. No Siri, iCloud or external publisher suggestions are simulated.</p>
    {:else if session.sheet==='clear-history'}<p>Clear read stories, local recommendation inputs, or both. Saved stories and followed channels will not change.</p>{#each [['history','Clear History'],['recommendations','Clear Recommendations'],['all','Clear All']] as [scope,label]}<button data-news-control={`clear:${scope}`} onclick={()=>request('news.history.clear',{scope})}>{label}</button>{/each}
    {:else}<p>{cap.disclosure}</p><p>Browse Today, discover and follow channels or topics, search the complete local text, save stories and revisit your reading history. Each article is complete original fiction. Share opens the actual local destination sheet; story alerts use the shared Notification Center. There is no live news, account, subscription purchase, host share or News+ content.</p><p>Mojave 10.14.0 News availability: United States, United Kingdom and Australia. Canada is a disclosed functional equivalent on that release. High Sierra and Windows have no native Apple News. Modern free-story layouts omit paid subscription surfaces.</p>{/if}
    {#if message}<p role="alert">{message}</p>{/if}<div class="news-dialog-actions"><button data-news-control="sheet:done" onclick={()=>request('news.sheet.close')}>Done</button></div>
  </section></div>{/if}
</section>
